type EM = { ready: void; data: { id: number }; error: { message: string } };
const em = new (TypedEmitter as new <T>()=>TypedEmitter<T>)<EM>();
let gotId = 0; let ready = false; let errMsg='';
em.on('data', (p) => { gotId = p.id; });
em.on('ready', () => { ready = true; });
em.on('error', (e) => { errMsg = e.message; });
em.emit('data', { id: 123 });
em.emit('ready', undefined);
em.emit('error', { message: 'oops' });
console.assert(ready && gotId===123 && errMsg==='oops', 'typed emitter failed');
// @ts-expect-error
// @ts-ignore
em.emit('data', { id: 'x' });

answer:
class TypedEmitter<M extends Record<string, any>> {
  private handlers: { [K in keyof M]?: Array<(p: M[K]) => void> } = {} as any;
  on<K extends keyof M>(event: K, fn: (payload: M[K]) => void): void {
    (this.handlers[event] ??= []).push(fn as any);
  }
  emit<K extends keyof M>(event: K, payload: M[K]): void {
    for (const fn of this.handlers[event] ?? []) (fn as any)(payload);
  }
}
